package com.example.datajpametamodel;

import jakarta.persistence.metamodel.SingularAttribute;

// These fields must be generated by Micronaut's metamodel processor.
public final class GeneratedTypes {
  public static SingularAttribute<Book, Long> id() {
    return Book_.id;
  }

  public static SingularAttribute<Book, String> title() {
    return Book_.title;
  }
}
